// Exact aliases identify exposure candidates, NOT confirmed affected versions.
const cfg = $('Configure inventory').first().json;
if (typeof cfg.dryRun !== 'boolean') throw new Error('dryRun must be a boolean');
if (!Array.isArray(cfg.inventory) || !cfg.inventory.length) throw new Error('Add an inventory first');
const norm = v => String(v).normalize('NFKC').trim().toLowerCase().replace(/\s+/g, ' ');
const clean = (v, max = 120) => String(v ?? '').replace(/[\r\n\t]/g, ' ').replace(/@/g, '＠').slice(0, max);
const inventory = cfg.inventory.map(row => {
  if (!row.label || !Array.isArray(row.vendorAliases) || !row.vendorAliases.length || !Array.isArray(row.productAliases) || !row.productAliases.length) throw new Error('Every inventory row needs label and non-empty alias arrays');
  if ([...row.vendorAliases, ...row.productAliases].some(v => typeof v !== 'string' || !norm(v))) throw new Error('Aliases must be non-empty strings');
  return { label: clean(row.label), vendors: [...new Set(row.vendorAliases.map(norm))].sort(), products: [...new Set(row.productAliases.map(norm))].sort() };
}).sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b)));
const catalog = $input.first().json;
if (!catalog || !Array.isArray(catalog.vulnerabilities) || !catalog.vulnerabilities.length || !catalog.dateReleased) throw new Error('Invalid or empty KEV catalog; no state changed');
if (Number(catalog.count) !== catalog.vulnerabilities.length) throw new Error('KEV count mismatch; no state changed');
const allIds = new Set();
for (const v of catalog.vulnerabilities) {
  if (!/^CVE-\d{4}-\d{4,}$/.test(v.cveID) || allIds.has(v.cveID) || typeof v.vendorProject !== 'string' || typeof v.product !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(v.dateAdded)) throw new Error('Malformed or duplicate KEV record; no state changed');
  allIds.add(v.cveID);
}
const matched = catalog.vulnerabilities.flatMap(v => {
  const groups = inventory.filter(row => row.vendors.includes(norm(v.vendorProject)) && row.products.includes(norm(v.product)));
  return groups.length ? [{ ...v, groups: groups.map(row => row.label) }] : [];
});
const key = JSON.stringify(inventory);
const state = $getWorkflowStaticData('global');
const existing = state.kevWatchV1;
const initialized = existing && existing.inventoryKey === key && Array.isArray(existing.seen);
if (!cfg.dryRun && !initialized) {
  state.kevWatchV1 = { inventoryKey: key, seen: [...allIds], initializedAt: new Date().toISOString(), lastCatalog: String(catalog.catalogVersion ?? '') };
  return [{ json: { send: false, mode: 'baseline', catalogCount: allIds.size, matchedCount: matched.length, note: 'Baseline recorded. No historical alerts sent. Publish/activate for persistence.' } }];
}
const seen = new Set(initialized ? existing.seen : []);
const candidates = matched.filter(v => !seen.has(v.cveID)).sort((a, b) => b.dateAdded.localeCompare(a.dateAdded) || a.cveID.localeCompare(b.cveID));
const selected = cfg.dryRun ? (initialized ? candidates : matched.sort((a,b) => b.dateAdded.localeCompare(a.dateAdded))).slice(0, Math.min(20, Math.max(1, Number(cfg.previewLimit) || 8))) : candidates;
if (!selected.length) return [{ json: { send: false, mode: cfg.dryRun ? 'preview' : 'no-change', catalogCount: allIds.size, matchedCount: matched.length, newMatches: 0 } }];
const header = 'KEV exposure candidates — verify affected versions before action.\n';
const chunks = [];
let content = header;
for (const v of selected) {
  const line = '\n' + v.cveID + ' | ' + clean(v.vendorProject, 60) + ' / ' + clean(v.product, 90) + '\nInventory: ' + clean(v.groups.join(', '), 120) + '\nAdded: ' + v.dateAdded + ' | CISA due: ' + clean(v.dueDate, 10) + '\nhttps://nvd.nist.gov/vuln/detail/' + v.cveID + '\n';
  if (content.length + line.length > 1700) { chunks.push(content); content = header; }
  content += line;
}
if (content !== header) chunks.push(content);
return chunks.map((content, index) => ({ json: { send: !cfg.dryRun, mode: cfg.dryRun ? 'preview' : 'alert', content, part: index + 1, parts: chunks.length, newMatches: candidates.length, selectedCount: selected.length, matchedCount: matched.length, inventoryKey: key, catalogVersion: String(catalog.catalogVersion ?? ''), catalogIds: [...allIds], catalogCount: allIds.size } }));

// Reached only if ALL Discord sends succeeded; leave Continue On Fail disabled.
const sent = $('Prepare digest').all().map(item => item.json);
if (!sent.length || sent.some(item => item.send !== true || item.mode !== 'alert')) throw new Error('No live sends to acknowledge');
if ($input.all().length !== sent.length) throw new Error('Discord response count mismatch; no acknowledgement');
const state = $getWorkflowStaticData('global');
if (!state.kevWatchV1 || state.kevWatchV1.inventoryKey !== sent[0].inventoryKey) throw new Error('Inventory changed; run again to initialize');
state.kevWatchV1.seen = sent[0].catalogIds;
state.kevWatchV1.lastCatalog = sent[0].catalogVersion;
state.kevWatchV1.lastSentAt = new Date().toISOString();
return [{json: {status: 'acknowledged', messages: sent.length, newMatches: sent[0].newMatches, catalogVersion: sent[0].catalogVersion}}];
